Simplified POTRI implementation:

```cpp
// File: rocsolver_potri_simple.hpp
#pragma once

#include "roclapack_trtri.hpp"
#include "rocblas.hpp"

template <typename T>
rocblas_status rocsolver_potri_simple(
    rocblas_handle handle,
    const rocblas_fill uplo,
    const rocblas_int n,
    T* A,
    const rocblas_int lda,
    rocblas_int* info)
{
    // 1. Argument validation
    if(!handle)
        return rocblas_status_invalid_handle;

    if(uplo != rocblas_fill_upper && uplo != rocblas_fill_lower)
        return rocblas_status_invalid_value;

    if(n < 0 || lda < n)
        return rocblas_status_invalid_size;

    if((n && !A) || !info)
        return rocblas_status_invalid_pointer;

    // Quick return
    if(n == 0) {
        *info = 0;
        return rocblas_status_success;
    }

    // 2. Workspace calculation
    size_t size_work1, size_work2, size_work3, size_work4;
    size_t size_tmpcopy, size_workArr;
    bool optim_mem;

    rocsolver_trtri_getMemorySize<false, false, T>(
        rocblas_diagonal_non_unit, n, 1,
        &size_work1, &size_work2, &size_work3, &size_work4,
        &size_tmpcopy, &size_workArr, &optim_mem);

    // Need n*n buffer for TRMM
    size_tmpcopy = std::max(size_tmpcopy, sizeof(T) * n * n);

    // 3. Allocate workspace
    void *work1, *work2, *work3, *work4, *tmpcopy, *workArr;
    rocblas_device_malloc mem(handle, size_work1, size_work2,
        size_work3, size_work4, size_tmpcopy, size_workArr);

    if(!mem)
        return rocblas_status_memory_error;

    work1 = mem[0];
    work2 = mem[1];
    work3 = mem[2];
    work4 = mem[3];
    tmpcopy = mem[4];
    workArr = mem[5];

    hipStream_t stream;
    rocblas_get_stream(handle, &stream);

    // 4. Triangular inverse (L^(-1) or U^(-1))
    rocblas_status status = rocsolver_trtri_template<false, false, T>(
        handle, uplo, rocblas_diagonal_non_unit, n,
        A, 0, lda, 0, info, 1,
        work1, work2, work3, work4,
        (T*)tmpcopy, (T**)workArr, optim_mem);

    if(status != rocblas_status_success)
        return status;

    // Check for singularity
    rocblas_int h_info;
    hipMemcpy(&h_info, info, sizeof(rocblas_int), hipMemcpyDeviceToHost);
    if(h_info > 0)
        return rocblas_status_success;  // Singular, A unchanged

    // 5. Copy inv(L) or inv(U) to tmpcopy
    rocblas_int blocks = (n - 1) / 32 + 1;
    ROCSOLVER_LAUNCH_KERNEL(
        (copy_mat<T>),
        dim3(blocks, blocks, 1), dim3(32, 32), 0, stream,
        copymat_to_buffer, n, n, A, 0, lda, 0,
        (T*)tmpcopy, no_mask{}, uplo);

    // 6. Compute inv(L)^T * inv(L) or inv(U) * inv(U)^T
    rocblas_pointer_mode old_mode;
    rocblas_get_pointer_mode(handle, &old_mode);
    rocblas_set_pointer_mode(handle, rocblas_pointer_mode_host);

    T one = 1.0;
    rocblas_side side = (uplo == rocblas_fill_upper ?
                         rocblas_side_right : rocblas_side_left);

    rocblasCall_trmm(
        handle, side, uplo,
        rocblas_operation_conjugate_transpose,
        rocblas_diagonal_non_unit,
        n, n, &one, 0,
        A, 0, lda, 0,              // inv(L) or inv(U)
        (T*)tmpcopy, 0, n, n*n,    // Source and result
        1, (T**)workArr);

    // 7. Copy result back to A
    ROCSOLVER_LAUNCH_KERNEL(
        (copy_mat<T>),
        dim3(blocks, blocks, 1), dim3(32, 32), 0, stream,
        copymat_from_buffer, n, n, A, 0, lda, 0,
        (T*)tmpcopy, no_mask{}, uplo,
        rocblas_diagonal_non_unit);

    rocblas_set_pointer_mode(handle, old_mode);
    return rocblas_status_success;
}

// C API wrapper
extern "C" rocblas_status rocsolver_spotri_simple(
    rocblas_handle handle,
    const rocblas_fill uplo,
    const rocblas_int n,
    float* A,
    const rocblas_int lda,
    rocblas_int* info)
{
    return rocsolver_potri_simple<float>(
        handle, uplo, n, A, lda, info);
}
```

Key simplifications:
- No save/restore around TRMM (assumes successful inversion)
- Non-batched only (batch_count=1)
- Checks info after TRTRI but doesn't preserve A on error
- Simpler but less robust than full POTRI

Usage:
```cpp
float A[9] = {4,2,1, 0,3,1, 0,0,2};  // Lower Cholesky factor
rocblas_int info;

rocsolver_spotri_simple(handle, rocblas_fill_lower, 3, A, 3, &info);

if(info == 0)
    printf("A now contains inverse\n");
else
    printf("Singular at position %d\n", info);
```
